(** The module, decoded. *)
Definition memrchr_module : module := Eval vm_compute in
  match decode_module memrchr_term with Some md => md | None => [] end.

(** The term decodes to the module. *)
Lemma memrchr_decodes : decode_module memrchr_term = Some memrchr_module.
Proof. vm_compute. reflexivity. Qed.

(** The function named n of the module, or an empty one. *)
Definition memrchr_fn (n : string) : func :=
  match find_direct (TAtom n) memrchr_module with
  | Some (Defined f) => f
  | _ => mkFunc (TAtom n) (TAtom "export") (RClass W) [] []
  end.

(** glibc's `__GI___memrchr`. *)
Definition glibc_memrchr : func := Eval vm_compute in memrchr_fn "__GI___memrchr".
